int atm_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    struct atm_vcc *vcc = ATM_SOCKET(sock);
    int val, len;

    if (get_user(len, optlen))
        return -EFAULT;

    if (level != SOL_SOCKET)
        return -ENOPROTOOPT;

    if (optname == SO_ATMQOS) {
        if (len < sizeof(struct atm_qos)) {
            if (put_user(sizeof(struct atm_qos), optlen))
                return -EFAULT;
            return -EINVAL;
        }
        if (copy_to_user(optval, &vcc->qos, sizeof(struct atm_qos)))
            return -EFAULT;
    } else if (vcc->dev && vcc->dev->ops && vcc->dev->ops->getsockopt) {
        return vcc->dev->ops->getsockopt(vcc, level, optname, optval, optlen);
    } else {
        return -ENOPROTOOPT;
    }

    return 0;
}

