int atm_getsockopt(struct socket *sock, int level, int optname,
                  char __user *optval, int __user *optlen)
{
    struct atm_vcc *vcc;
    int len, err = 0;

    if (optlen == NULL) {
        return -EFAULT;
    }

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    vcc = ATM_SOCKET(sock)->vcc;
    if (!vcc)
        return -ENOTCONN;

    if (level == SOL_ATM) {
        switch (optname) {
            case ATM_SO_QOS:
                if (len < sizeof(struct atm_qos)) {
                    len = sizeof(struct atm_qos);
                    return -EINVAL;
                }
                if (copy_to_user(optval, &vcc->qos, sizeof(struct atm_qos)))
                    return -EFAULT;
                break;
            case ATM_SO_AAL:
                if (len < sizeof(int)) {
                    return -EINVAL;
                }
                if (put_user(vcc->aal, (int __user *)optval))
                    return -EFAULT;
                break;
            default:
                return vcc->dev->ops->getsockopt(sock, level, optname, optval, optlen);
        }
    } else {
        return sock->ops->getsockopt(sock, level, optname, optval, optlen);
    }

    return err;
}

#include <linux/atm.h>
#include <linux/socket.h>
#include <linux/uaccess.h>

int atm_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    struct atm_vcc *vcc;

    if (!optlen || !optval) {
        return -EFAULT;
    }

    vcc = ATM_SOCKET(sk(sock))->vcc;
    if (!vcc) {
        return -ENOTCONN;
    }

    switch (optname) {
        case SO_ATMQOS:
        {
            struct atm_qos qos;
            if (copy_from_user(&qos, &vcc->qos, sizeof(qos))) {
                return -EFAULT;
            }
            if (copy_to_user(optval, &qos, sizeof(qos))) {
                return -EFAULT;
            }
            ret = sizeof(qos);
            break;
        }
        default:
        {
            if (vcc->dev && vcc->dev->ops->getsockopt) {
                ret = vcc->dev->ops->getsockopt(vcc, level, optname, optval, optlen);
            } else {
                ret = -EINVAL;
            }
        }
    }

    if (copy_to_user(optlen, &ret, sizeof(int))) {
        return -EFAULT;
    }

    return 0;
}
